import json
entries={}
def add(id,name,latin,system,region,description,function,clinical,related,layer=4,sex='both',aliases=None):
 entries[id]={'id':id,'meshName':id,'displayName':name,'latinName':latin,'system':system,'region':region,'description':description,'function':function,'clinicalNotes':clinical,'relatedIds':related.split(','),'layer':layer,'sex':sex,'aliases':aliases or []}
add('skull','Skull','Cranium','skeletal','head-neck','The bony framework of the head; the cranial vault encloses the brain.','Protects the brain and supports the face.','Observe head symmetry and report injury-related changes in consciousness.','brain,mandible,spine',5)
add('mandible','Mandible','Mandibula','skeletal','head-neck','The lower jaw articulates with the temporal bones at the temporomandibular joints.','Supports lower teeth and moves during chewing.','Assess jaw movement and ask about pain or difficulty opening the mouth.','skull',5)
add('spine','Vertebral column','Columna vertebralis','skeletal','thorax','Extends from the skull to the pelvis; spinous processes form posterior midline landmarks.','Supports the trunk and encloses the spinal cord.','Observe posture and spinal alignment; new weakness after spinal injury requires urgent escalation.','spinal_cord,pelvis,ribs',5,aliases=['spine','backbone'])
add('ribs','Rib cage','Costae','skeletal','thorax','Twelve paired ribs curve around the thorax and attach posteriorly to thoracic vertebrae.','Protects thoracic organs and moves during breathing.','Use intercostal spaces to orient chest assessment and compare chest expansion.','sternum,lungs_left,lungs_right',5,aliases=['ribs','thoracic cage'])
add('sternum','Sternum','Sternum','skeletal','thorax','Midline anterior chest bone with manubrium, body, and xiphoid process.','Anchors ribs through costal cartilage and protects the mediastinum.','The sternal angle helps locate the second rib for chest landmarks.','ribs,heart',5,aliases=['breastbone'])
add('pelvis','Bony pelvis','Pelvis ossea','skeletal','pelvis','The hip bones join the sacrum posteriorly and the pubic symphysis anteriorly.','Transfers body weight and protects pelvic organs.','Recognize pelvic landmarks when assessing mobility and locating the hip region.','femur_left,femur_right,bladder',5)
bilateral=[
('clavicle','Clavicle','Clavicula','skeletal','upper-limb','Runs between the sternum and shoulder at the upper chest.','Braces the shoulder away from the trunk.','Inspect for asymmetry or tenderness after a fall.','sternum,scapula',5),
('scapula','Scapula','Scapula','skeletal','upper-limb','Flat posterior shoulder bone; the acromion is palpable at its lateral end.','Provides attachment for shoulder muscles.','The acromion is a reference landmark for deltoid assessment.','clavicle,deltoid',5),
('humerus','Humerus','Humerus','skeletal','upper-limb','Extends from the shoulder to the elbow; the head articulates with the scapula.','Forms the arm lever for shoulder and elbow movement.','Assess distal circulation, sensation, and movement with suspected injury.','radius,ulna,deltoid',5),
('radius','Radius','Radius','skeletal','upper-limb','Forearm bone on the thumb side in anatomical position.','Transmits wrist forces and rotates around the ulna.','The radial pulse is felt at the thumb side of the wrist.','ulna,humerus',5),
('ulna','Ulna','Ulna','skeletal','upper-limb','Medial forearm bone; its olecranon forms the point of the elbow.','Stabilizes the forearm and forms the elbow hinge.','Observe elbow swelling and protect the olecranon from sustained pressure.','radius,humerus',5),
('hand','Hand bones','Ossa manus','skeletal','upper-limb','Carpals form the wrist; metacarpals and phalanges extend into the hand and fingers.','Supports grip and fine movement.','Compare grip, finger movement, skin temperature, and capillary refill.','radius,ulna',5),
('femur','Femur','Femur','skeletal','lower-limb','Extends from hip to knee; its greater trochanter is a lateral hip landmark.','Bears weight and provides leverage for walking.','Assess limb alignment and distal neurovascular status after suspected fracture.','pelvis,patella,tibia',5),
('patella','Patella','Patella','skeletal','lower-limb','Sesamoid bone within the quadriceps tendon at the front of the knee.','Improves leverage of the knee extensor muscles.','Inspect swelling and observe active knee extension when appropriate.','femur,tibia',5),
('tibia','Tibia','Tibia','skeletal','lower-limb','Large medial leg bone; its anterior border forms the shin.','Transmits weight from knee to ankle.','Assess the pretibial region for edema and skin changes.','fibula,patella',5),
('fibula','Fibula','Fibula','skeletal','lower-limb','Slender lateral leg bone ending at the lateral malleolus.','Stabilizes the ankle and anchors muscles.','Include the lateral ankle in swelling and skin assessment.','tibia,foot',5),
('foot','Foot bones','Ossa pedis','skeletal','lower-limb','Tarsals, metatarsals, and phalanges form the heel, arches, and toes.','Supports weight and assists propulsion.','Inspect pressure areas and skin integrity, especially with reduced sensation.','tibia,fibula',5),
('deltoid','Deltoid','Musculus deltoideus','muscular','upper-limb','Covers the shoulder below the acromion and inserts on the humerus.','Abducts the arm; its fibers also assist flexion and extension.','Recognize the deltoid IM region; use supervised landmarking and patient-specific site selection.','humerus,scapula',2),
('biceps','Biceps brachii','Musculus biceps brachii','muscular','upper-limb','Superficial anterior upper arm muscle with two proximal heads.','Flexes the elbow and supinates the forearm.','Compare elbow flexion strength when assessing motor function.','humerus,radius',2),
('triceps','Triceps brachii','Musculus triceps brachii','muscular','upper-limb','Muscle of the posterior upper arm attaching to the olecranon.','Extends the elbow.','Compare resisted elbow extension as part of a motor assessment.','humerus,ulna',2),
('pectoralis','Pectoralis major','Musculus pectoralis major','muscular','thorax','Fan-shaped superficial muscle spanning the anterior upper chest.','Adducts and medially rotates the arm.','Observe symmetry and arm movement; auscultation landmarks relate to ribs beneath this muscle.','sternum,humerus',2),
('vastus','Vastus lateralis','Musculus vastus lateralis','muscular','lower-limb','Quadriceps muscle on the lateral thigh between hip and knee.','Extends the knee.','Recognize the middle anterolateral thigh as an IM region; confirm landmarks with an instructor.','femur,patella',2),
('gluteus','Gluteus medius','Musculus gluteus medius','muscular','pelvis','Lateral hip muscle between the ilium and greater trochanter.','Abducts the hip and stabilizes the pelvis during gait.','The ventrogluteal IM region overlies gluteus medius and minimus; surface markers are approximate.','pelvis,femur',3),
('gastrocnemius','Gastrocnemius','Musculus gastrocnemius','muscular','lower-limb','Superficial posterior calf muscle joining the calcaneal tendon.','Plantarflexes the foot and assists knee flexion.','Observe gait and calf symmetry; report new unilateral swelling or pain.','tibia,foot',2),
('kidney','Kidney','Ren','urinary','abdomen','Retroperitoneal organ on the posterior abdominal wall; the right kidney sits slightly lower.','Filters plasma and regulates fluid, electrolytes, and acid-base balance.','Track urine output and fluid balance; assess flank discomfort in context.','ureter,bladder',4),
('ureter','Ureter','Ureter','urinary','abdomen','Muscular tube running from the renal pelvis to the bladder.','Propels urine toward the bladder.','Colicky flank pain radiating toward the groin can reflect ureteric obstruction.','kidney,bladder',4),
('adrenal','Adrenal gland','Glandula suprarenalis','endocrine','abdomen','Small gland at the superior pole of each kidney.','Produces hormones involved in stress response and salt balance.','Recognize the link between adrenal hormones, blood pressure, and electrolyte changes.','kidney',4),
('sciatic','Sciatic nerve','Nervus ischiadicus','nervous','lower-limb','Large nerve from the sacral plexus traveling through the posterior thigh.','Carries motor and sensory fibers to much of the lower limb.','Assess new radiating leg pain, weakness, and sensory changes.','spinal_cord,gluteus',4),
]
for base,name,latin,system,region,description,function,clinical,related,layer in bilateral:
 for side in ['left','right']:
  rel=','.join(x+'_'+side if any(t[0]==x for t in bilateral) else x for x in related.split(','))
  add(base+'_'+side,side.title()+' '+name.lower(),latin+' ('+side+')',system,region,description,function,clinical,rel,layer,aliases=[name+' '+side])
add('heart','Heart','Cor','cardiovascular','thorax','In the mediastinum between the lungs, behind the sternum. The apex points inferiorly and to the left.','Pumps blood through pulmonary and systemic circulation, delivering oxygen and nutrients to tissues.','Connect the apical pulse with the left fifth intercostal space at the midclavicular line. Assess rate and rhythm.','aorta,lungs_left,lungs_right,sternum',4)
add('aorta','Aorta','Aorta','cardiovascular','thorax','Leaves the left ventricle, arches superiorly, then descends through the thorax and abdomen.','Distributes oxygenated blood to systemic arteries.','Compare peripheral perfusion findings; sudden severe chest or back pain needs prompt escalation.','heart,arteries',4)
add('arteries','Systemic arteries','Arteriae','cardiovascular','upper-limb','Branching vessels extend from the aorta to the head, arms, trunk, and legs.','Carry blood away from the heart.','Compare accessible peripheral pulses for strength and symmetry.','heart,aorta,veins',4)
add('veins','Systemic veins','Venae','cardiovascular','upper-limb','Superficial and deep channels return blood from body tissues.','Return blood toward the heart.','Observe edema and superficial vein sites; assess IV sites for pain, redness, swelling, or leakage.','heart,arteries',4)
for side in ['left','right']:
 add('lungs_'+side,side.title()+' lung','Pulmo '+('sinister' if side=='left' else 'dexter'),'respiratory','thorax',('Two-lobed organ with a cardiac notch in the left thoracic cavity.' if side=='left' else 'Three-lobed organ in the right thoracic cavity above the diaphragm.'),'Exchanges oxygen and carbon dioxide at the alveoli.','Compare breath sounds side to side and assess respiratory effort. This model does not resolve alveoli or lung fissures.','trachea,diaphragm,heart',4)
add('trachea','Trachea','Trachea','respiratory','head-neck','Airway anterior to the esophagus, dividing into the main bronchi.','Conducts air toward and away from the lungs.','Observe work of breathing and listen for abnormal upper-airway sounds.','lungs_left,lungs_right,esophagus',4,aliases=['windpipe'])
add('diaphragm','Diaphragm','Diaphragma','muscular','thorax','Dome-shaped muscle separating the thoracic and abdominal cavities.','Contracts and descends to increase thoracic volume during inspiration.','Observe the breathing pattern and use of accessory muscles.','lungs_left,lungs_right,liver',3)
add('esophagus','Esophagus','Oesophagus','digestive','thorax','Muscular tube posterior to the trachea passing through the diaphragm to the stomach.','Moves swallowed material into the stomach.','Ask about swallowing difficulty and observe for aspiration-related symptoms.','trachea,stomach',4,aliases=['oesophagus'])
add('liver','Liver','Hepar','digestive','abdomen','Large organ mainly in the right upper quadrant beneath the diaphragm.','Processes nutrients, produces bile, and synthesizes plasma proteins.','Assess for jaundice and changes in abdominal contour; interpret findings with the clinical team.','gallbladder,diaphragm,stomach',4)
add('gallbladder','Gallbladder','Vesica biliaris','digestive','abdomen','Small sac on the inferior surface of the liver.','Stores and concentrates bile.','Note right upper quadrant pain and associated nausea or food-related symptoms.','liver,small_intestine',4)
add('stomach','Stomach','Gaster','digestive','abdomen','Expandable hollow organ in the left upper abdomen between esophagus and duodenum.','Mixes food with acid and begins protein digestion.','Ask about nausea, vomiting, intake, and epigastric discomfort.','esophagus,small_intestine,pancreas',4)
add('small_intestine','Small intestine','Intestinum tenue','digestive','abdomen','Coiled duodenum, jejunum, and ileum within the central abdomen.','Digests food and absorbs most nutrients.','Assess abdominal symptoms and hydration; consider intake and stool changes together.','stomach,colon',4)
add('colon','Large intestine','Intestinum crassum','digestive','abdomen','Frames the small intestine, rising on the right and descending on the left.','Absorbs water and electrolytes and forms stool.','Ask about usual bowel patterns and report significant changes or bleeding.','small_intestine',4,aliases=['colon','large bowel'])
add('pancreas','Pancreas','Pancreas','endocrine','abdomen','Elongated gland posterior to the stomach, extending toward the spleen.','Produces digestive enzymes and hormones that regulate blood glucose.','Relate glucose monitoring and hypoglycemia symptoms to pancreatic hormone function.','stomach,small_intestine',4)
add('brain','Brain','Encephalon','nervous','head-neck','Central nervous tissue inside the cranial cavity.','Integrates sensory input and controls cognition, movement, and autonomic functions.','Assess consciousness, orientation, speech, pupil response, and new focal deficits.','skull,spinal_cord',4)
add('spinal_cord','Spinal cord','Medulla spinalis','nervous','thorax','Nervous tissue in the vertebral canal, ending near the L1–L2 vertebral level in adults.','Relays signals and coordinates spinal reflexes.','Assess limb motor and sensory function; escalate sudden deficits.','brain,spine,sciatic_left,sciatic_right',4)
add('bladder','Urinary bladder','Vesica urinaria','urinary','pelvis','Hollow muscular organ posterior to the pubic symphysis.','Stores urine before voiding.','Assess voiding patterns, output, and suprapubic discomfort or distension.','kidney_left,kidney_right,ureter_left,ureter_right',4)
add('thyroid','Thyroid gland','Glandula thyroidea','endocrine','head-neck','Butterfly-shaped gland in the anterior neck on either side of the upper trachea.','Secretes hormones regulating metabolism.','Observe neck enlargement and consider heart rate, temperature tolerance, and energy changes.','trachea',4)
add('spleen','Spleen','Lien','lymphatic','abdomen','Organ in the left upper quadrant, lateral and posterior to the stomach.','Filters blood and supports immune responses.','Recognize its location when assessing left upper abdominal injury.','stomach,liver',4)
add('lymph_nodes','Lymph nodes','Nodi lymphoidei','lymphatic','head-neck','Small lymphatic filters clustered in cervical, axillary, and inguinal regions.','Filter lymph and support immune cell activation.','Assess accessible nodes for size, tenderness, and mobility when indicated.','spleen',4)
add('skin','Skin','Cutis','integumentary','thorax','Outer covering of the body, with epidermis and dermis.','Provides a barrier, sensation, and temperature regulation.','Inspect color, temperature, moisture, and pressure-prone areas.','fat',0)
add('fat','Subcutaneous tissue','Tela subcutanea','integumentary','thorax','Adipose and connective tissue beneath the dermis.','Cushions tissues, stores energy, and limits heat loss.','Tissue depth varies by person and site; assess it before supervised injection planning.','skin,deltoid_left',1,aliases=['fat','hypodermis'])
add('uterus','Uterus','Uterus','reproductive','pelvis','Muscular pelvic organ between the bladder and rectum.','Supports implantation, fetal development, and labor.','Relate pelvic symptoms and reproductive history to anatomy; provide privacy and consent.','ovaries,bladder',4,'female')
add('ovaries','Ovaries','Ovaria','reproductive','pelvis','Paired gonads lateral to the uterus.','Produce oocytes and reproductive hormones.','Ask sensitively about menstrual changes and pelvic discomfort.','uterus',4,'female')
add('prostate','Prostate','Prostata','reproductive','pelvis','Gland inferior to the bladder surrounding the proximal urethra.','Contributes fluid to semen.','Ask about urinary hesitancy, weak stream, and incomplete emptying.','bladder,testes',4,'male')
add('testes','Testes','Testes','reproductive','pelvis','Paired gonads within the scrotum, outside the pelvic cavity.','Produce sperm and testosterone.','New acute testicular pain or swelling needs prompt assessment.','prostate',4,'male')
